/**
 * Testimonials 5 Component
 *
 * Source: @irsyad/testimonials-05 (IntentUI)
 * License: Pro Subscription
 *
 * Modifications:
 * - Integrated with PayloadCMS block system
 * - Replaced hardcoded content with dynamic props
 * - Converted from page component to reusable block component
 */

import { Avatar } from "@/registry/ui/avatar-intentui";
import { CardDescription, CardHeader, CardTitle } from "@/registry/ui/card";
import { Container } from "@/registry/ui/container";
import type { Testimonials_5_Block } from "~/payload-types";

export default function Testimonials5Section(props: Testimonials_5_Block) {
	return (
		<Container className="py-6 sm:py-16">
			<h1 className="sr-only">Testimonials</h1>
			<div className="mx-auto max-w-xl text-center">
				<blockquote className="font-light text-2xl text-muted-fg italic leading-relaxed">
					"{props.quote}"
				</blockquote>
				<div className="mt-8 flex flex-col items-center gap-4">
					<Avatar
						src={props.authorImage}
						alt={props.authorName}
						size="2xl"
						className="ring-2 ring-primary/50 ring-offset-2"
					/>
					<CardHeader>
						<CardTitle>{props.authorName}</CardTitle>
						<CardDescription>{props.authorRole}</CardDescription>
					</CardHeader>
				</div>
			</div>
		</Container>
	);
}

import type { Block } from "payload";

import {
	BLOCK_GROUP_TESTIMONIALS,
	BLOCK_SLUG_TESTIMONIALS_5,
} from "@/registry/default/lib/constants/blocks";

export const Testimonials_5_Block: Block = {
	slug: BLOCK_SLUG_TESTIMONIALS_5,
	admin: {
		group: BLOCK_GROUP_TESTIMONIALS,
	},
	fields: [
		{
			type: "collapsible",
			label: "Testimonial Content",
			admin: {
				initCollapsed: false,
			},
			fields: [
				{
					name: "quote",
					type: "textarea",
					label: "Quote",
					required: true,
					defaultValue:
						"We cut dev time in half and actually enjoyed the process. Everything feels designed for speed and clarity — it just makes sense.",
				},
			],
		},
		{
			type: "collapsible",
			label: "Author Information",
			admin: {
				initCollapsed: false,
			},
			fields: [
				{
					name: "authorName",
					type: "text",
					label: "Author Name",
					required: true,
					defaultValue: "Lena Fischer",
				},
				{
					name: "authorRole",
					type: "text",
					label: "Author Role/Title",
					required: true,
					defaultValue: "Lead Frontend Engineer at Skyloft",
				},
				{
					name: "authorImage",
					type: "text",
					label: "Author Image URL",
					required: true,
					defaultValue: "https://randomuser.me/api/portraits/women/52.jpg",
				},
			],
		},
	],
	interfaceName: "Testimonials_5_Block",
	labels: {
		plural: "Testimonials 5's",
		singular: "Testimonials 5",
	},
};
